{
  "verdict": "CHANGES",
  "findings": [
    {
      "scope": "SPEC",
      "severity": "medium",
      "reference": "Task Card lines 1–3, rejection criteria",
      "problem": "The below-minimum rejection rule is only implicit in the objective. State it explicitly in the Task Card and add acceptance cases for it and the already specified nonpositive-step rejection.",
      "example": "With minVolume=0.25 and maxVolume=1.0, request=0.125 and step=0.25 must return 0. With the same bounds and request=0.5, test step=0 and step=-0.25 separately. Both must return 0."
    },
    {
      "scope": "SPEC",
      "severity": "medium",
      "reference": "Task Card line 3, above-maximum acceptance case",
      "problem": "The above-maximum case does not require a maximum that falls between grid points. Testing only an on-grid maximum would miss an implementation that clamps directly to the maximum and returns an invalid volume.",
      "example": "With request=1.25, minVolume=0.25, maxVolume=0.875, and step=0.25, expect 0.75."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "Volume.mqh, below-minimum return",
      "problem": "Returning minVolume for a below-minimum request exceeds the requested exposure and replaces the zero sentinel the caller uses to skip the order.",
      "example": "With request=0.125, minVolume=0.25, maxVolume=1.0, and step=0.25, the new code returns 0.25. The expected result is 0."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "Volume.mqh, removed nonpositive-step guard",
      "problem": "Removing the step guard breaks the required zero return for invalid metadata. A zero step reaches division by zero, and a negative step can produce a nonzero volume.",
      "example": "With request=0.5, minVolume=0.25, and maxVolume=1.0, step=0 reaches division by zero and step=-0.25 returns 0.5. Both inputs must return 0."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "Volume.mqh, MathCeil replacing MathFloor",
      "problem": "Rounding up after applying the cap can exceed either the requested volume or the broker maximum. Restore downward quantization on the minimum-anchored grid.",
      "example": "With minVolume=0.25 and step=0.25, request=0.625 and maxVolume=1.0 returns 0.75 instead of 0.5. With request=1.25 and maxVolume=0.875, it returns 1.0 instead of 0.75."
    }
  ]
}
